const q=$input.first().json.query;
const ok=q&&typeof q==='object'&&!Array.isArray(q)&&Object.keys(q).length===1&&Object.hasOwn(q,'folio')&&typeof q.folio==='string'&&q.folio.length<=64;
const folio=ok?q.folio.trim().toUpperCase():'';
if(!ok||!(/^(?:MUESTRA-[0-9]{3,}|RESUMEN)$/.test(folio)))return [{json:{permitida:false,status:400,body:{datos_ficticios:true,tipo:'error',encontrado:false,error:'ENTRADA_NO_PERMITIDA',mensaje:'Usa un folio público MUESTRA-001 o RESUMEN; consulta de solo lectura.'}}}];
return [{json:{permitida:true,folio}}];

const p=$input.first().json;
const fail=()=>[{json:{status:503,body:{datos_ficticios:true,tipo:'error',encontrado:false,error:'FUENTE_NO_DISPONIBLE',mensaje:'No se pudo verificar la consulta. Usa el dashboard o Telegram; no se confirma un estado.'}}}];
const states=['PENDIENTE_APROBACION','APROBADA','RECHAZADA','DETENIDO','ACLARACION_REQUERIDA','DEVUELTO','ERROR_INCONSISTENTE'];
const allowed=['fuente','datos_ficticios','consultado_en','zona_horaria','tipo','encontrado','registro','nota','total_registros','por_estado','importados_simulados','error','mensaje'];
if(!p||p.datos_ficticios!==true||p.fuente!=='Data Table LogiSmart'||!Number.isFinite(Date.parse(p.consultado_en))||Object.keys(p).some(k=>!allowed.includes(k)))return fail();
if(p.tipo==='consulta_folio'){
 if(typeof p.encontrado!=='boolean'||(p.encontrado&&!p.registro)||(!p.encontrado&&p.registro!==null))return fail();
 if(p.registro){
  const r=p.registro;const fields=['folio_publico','fecha_registro','productos','importe_total','moneda','estado_final','aprobacion_humana','duracion_total_ms','origen','completa_primer_intento','sin_correcciones_auditoria'];
  if(Object.keys(r).some(k=>!fields.includes(k))||!/^MUESTRA-[0-9]{3,}$/.test(r.folio_publico)||!states.includes(r.estado_final)||!Array.isArray(r.productos)||!r.productos.every(x=>['Producto A','Producto B'].includes(x)))return fail();
 }
}else if(p.tipo==='resumen'){
 if(!Number.isSafeInteger(p.total_registros)||p.total_registros<0||!p.por_estado||Object.keys(p.por_estado).some(k=>!states.includes(k))||Object.values(p.por_estado).some(v=>!Number.isSafeInteger(v)||v<0)||Object.values(p.por_estado).reduce((a,b)=>a+b,0)!==p.total_registros)return fail();
}else return fail();
return [{json:{status:200,body:p}}];
